// Minimal actor-based cache for RelayFeed items
actor RelayCache {
  private var items: [String: FeedItem] = [:]
  func upsert(_ item: FeedItem) { items[item.id] = item }
  func all() -> [FeedItem] { Array(items.values) }
}
